module GeometricPointTests

using Hecke
using Test

const _GROUPS = (:helpers, :parents, :evaluation, :coordinates, :places,
                 :convenience, :equality, :branches, :divisors, :display)
const _AVAILABLE_GROUPS = (_GROUPS..., :irreducibility)
const _POLE_ERROR = Union{ArgumentError, ErrorException}

_qq(values...) = QQBarFieldElem[QQBar(a) for a in values]

function _same_projective(a, b)
    length(a) == length(b) == 3 || return false
    all(iszero, a) && return false
    all(iszero, b) && return false
    return all(a[i] * b[j] == a[j] * b[i] for i in 1:3 for j in i+1:3)
end

# Independent fixtures: do not construct fields through the helper being tested.
function _field(eq)
    K, x = rational_function_field(QQBar, :gp_test_x; cached=false)
    _, Y = polynomial_ring(K, :gp_test_Y; cached=false)
    F, y = function_field(eq(x, Y), :gp_test_y; cached=false)
    return F, F(x), y
end

function _infinite_places(F)
    O = infinite_maximal_order(F)
    t = base_ring(O)(inv(gen(base_ring(F))))
    return [p for (p, _) in factor(ideal(O, t))]
end

function _finite_fibre(F, a)
    O = finite_maximal_order(F)
    q = gen(base_ring(O)) - QQBar(a)
    return [p for (p, _) in factor(ideal(O, q))]
end

function _finite_prime(F, a, b)
    O = finite_maximal_order(F)
    x, y = F(gen(base_ring(F))), gen(F)
    return only(p for (p, _) in factor(ideal(O, x - QQBar(a), y - QQBar(b))))
end

# Check exact geometry and field identities, without imposing a normalization
# on the stored projective coordinates or comparing pretty-printed strings.
function _check_point(api, P, expected; curve, singular, infinite)
    @test P isa api.GeometricPoint
    @test parent(P) === curve
    @test P.parent_object === curve
    @test function_field(P) === function_field(curve)
    @test api.plane_equation(P) === api.plane_equation(curve)
    @test coordinates(P) isa NTuple{3, QQBarFieldElem}
    @test _same_projective(coordinates(P), expected)
    @test api.is_singular(P) === singular
    @test api.is_infinite(P) === infinite
    @test defining_constant_field(function_field(P)) === QQBar
    @test iszero(api.homogenise(api.plane_equation(P))(coordinates(P)...))
end

function _check_cache_and_chart(api, P)
    F = function_field(P)
    x, y = F(gen(base_ring(F))), gen(F)

    p = api.place(P)
    @test p isa Hecke.GenOrdIdl
    @test is_prime(p)
    @test Hecke.field(order(p)) === F
    @test P.place === p
    @test api.place(P) === p
    api.assure_has_place(P)
    @test P.place === p

    ev = api.evaluate(P)
    @test ev isa MapFromFunc
    @test domain(ev) === F
    @test codomain(ev) === QQBar
    @test P.ev === ev
    @test api.evaluate(P) === ev
    api.assure_has_ev(P)
    @test P.ev === ev

    @test ev(zero(F)) == 0
    @test ev(one(F)) == 1
    @test ev(F(7)) == 7
    @test parent(ev(F(7))) === QQBar

    a, b, z = coordinates(P)
    if !iszero(z)
        f, g = x, y
        @test ev(f) == a/z
        @test ev(g) == b/z
    elseif !iszero(a)
        f, g = inv(x), y/x
        @test iszero(ev(f))
        @test ev(g) == b/a
    else
        f, g = inv(y), x/y
        @test iszero(ev(f))
        @test ev(g) == a/b
    end

    @test ev(f + g) == ev(f) + ev(g)
    @test ev(f - g) == ev(f) - ev(g)
    @test ev(f * g) == ev(f) * ev(g)
    return ev
end

function _test_helpers(api)
    R, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)

    @testset "Monicity in the second coordinate" begin
        for eq in (Y, Y^2 - X^3, Y^2 + X*Y + X^5 + 1)
            @test api.is_monic_in_2nd_coord(eq)
        end
        for eq in (zero(R), 2Y^2 - X^3, X*Y^2 + Y + 1, X*Y - 1, X + 1)
            @test !api.is_monic_in_2nd_coord(eq)
        end
    end

    @testset "Homogenization" begin
        eq = Y^2 - X^3 + 2X + 3
        H = api.homogenise(eq)
        A, B, Z = gens(parent(H))
        @test base_ring(parent(H)) === QQBar
        @test H == B^2*Z - A^3 + 2A*Z^2 + 3Z^3
        @test H(X, Y, one(R)) == eq
        @test all(sum(exponents) == 3 for exponents in exponent_vectors(H))
        @test H(QQBar(0), QQBar(1), QQBar(0)) == 0
        @test api.homogenise(zero(R)) == 0
        @test api.homogenise(R(5)) == 5
    end

    @testset "Plane equation / function field conversion" begin
        eq = Y^2 - X^3 + X
        F = api.plane_equation_to_function_field(eq)
        x, y = F(gen(base_ring(F))), gen(F)
        @test defining_constant_field(F) === QQBar
        @test iszero(eq(x, y))
        recovered = api.function_field_to_plane_equation(F)
        @test recovered(X, Y) == eq
        @test iszero(recovered(x, y))

        @testset "Rational coefficients" begin
            _, (U, V) = polynomial_ring(QQ, [:gp_U, :gp_V]; cached=false)
            G = api.plane_equation_to_function_field(V^2 - U^3 + U)
            u, v = G(gen(base_ring(G))), gen(G)
            @test defining_constant_field(G) === QQBar
            @test iszero(v^2 - u^3 + u)
        end

        @testset "Number field coefficients, independent of embedding choice" begin
            k, a = quadratic_field(2; cached=false)
            _, (U, V) = polynomial_ring(k, [:gp_U, :gp_V]; cached=false)
            G = api.plane_equation_to_function_field(V^2 - U^3 - a)
            u, v = G(gen(base_ring(G))), gen(G)
            @test defining_constant_field(G) === QQBar
            # Either embedding of sqrt(2) is valid.
            @test (v^2 - u^3)^2 == G(2)
        end

        @testset "Rejected conversion inputs" begin
            _, (U, V, W) = polynomial_ring(QQBar, [:gp_U, :gp_V, :gp_W]; cached=false)
            @test_throws AssertionError api.plane_equation_to_function_field(V^2 - U - W)
            _, (U5, V5) = polynomial_ring(GF(5), [:gp_U5, :gp_V5]; cached=false)
            @test_throws _POLE_ERROR api.plane_equation_to_function_field(V5^2 - U5)
        end
    end
end

function _test_evaluation(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)

    @testset "Finite unramified places and removable denominators" begin
        F, x, y = _field(Y^2 - X^2 - 1)
        for c in (-1, 1)
            @testset "y = $c above x = 0" begin
                p = _finite_prime(F, 0, c)
                ev = api.evaluate(p)
                @test domain(ev) === F
                @test codomain(ev) === QQBar
                @test ev(zero(F)) == 0
                @test ev(F(3)) == 3
                @test parent(ev(x)) === QQBar
                @test ev(x) == 0
                @test ev(y) == c
                # (y-c)(y+c)=x^2: cancellation at this branch only.
                @test ev((y-c)/x^2) == QQBar(c)/2
                @test ev(inv(y+c)) == QQBar(c)/2
                @test ev(inv(y)) == c
                @test_throws _POLE_ERROR ev(inv(x))
                @test_throws _POLE_ERROR ev((y+c)/x^2)
                @test ev(x+y) == ev(x)+ev(y)
                @test ev((x+1)*y) == ev(x+1)*ev(y)
            end
        end
    end

    @testset "Ramified finite place and a non-power order basis" begin
        F, x, y = _field(Y^2 - X^3)
        p = only(_finite_fibre(F, 0))
        @test Hecke.ramification_index(p) == 2
        ev = api.evaluate(p)
        @test ev(x) == 0
        @test ev(y) == 0
        @test ev(y/x) == 0
        @test ev((y+x)/x) == 1
        @test ev(y^2/x^3) == 1
        @test_throws _POLE_ERROR ev(x/y)
    end

    @testset "Finite node: evaluation separates branches" begin
        F, x, y = _field(Y^2 - X^2*(X+1))
        ps = _finite_fibre(F, 0)
        @test length(ps) == 2
        residues = QQBarFieldElem[]
        for p in ps
            ev = api.evaluate(p)
            c = ev(y/x)
            push!(residues, c)
            @test c^2 == 1
            @test ev((y-c*x)/x^2) == c/2
            @test ev(inv(y/x+c)) == c/2
            @test_throws _POLE_ERROR ev((y+c*x)/x^2)
        end
        @test Set(residues) == Set(_qq(-1, 1))
    end

    @testset "Split infinity: cancellation with poles at the other branch" begin
        F, x, y = _field(Y^2 - X^4 - 1)
        ps = _infinite_places(F)
        @test length(ps) == 2
        residues = QQBarFieldElem[]
        for p in ps
            ev = api.evaluate(p)
            c = ev(y/x^2)
            push!(residues, c)
            @test c^2 == 1
            @test ev(inv(x)) == 0
            @test ev(x/y) == 0
            @test ev(x/(x+1)) == 1
            @test ev(x^2*(y-c*x^2)) == c/2
            @test ev(inv(y/x^2+c)) == c/2
            @test_throws _POLE_ERROR ev(x)
            @test_throws _POLE_ERROR ev(x^2*(y+c*x^2))
        end
        @test Set(residues) == Set(_qq(-1, 1))
    end

    @testset "Ramified infinity" begin
        F, x, y = _field(Y^2 - X^5)
        p = only(_infinite_places(F))
        @test Hecke.ramification_index(p) == 2
        ev = api.evaluate(p)
        @test ev(x/y) == 0
        @test ev(inv(y)) == 0
        @test ev(y^2/x^5) == 1
        @test_throws _POLE_ERROR ev(y/x)
    end
end

function _test_coordinates(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    conic = Y^2 - X^2 - 1
    Cconic = api.punctured_marked_curve(conic)

    @testset "Smooth affine and projectively rescaled input; lazy caches" begin
        sqrt2 = sqrt(QQBar(2))
        imaginary_unit = sqrt(QQBar(-1))
        inputs = [(_qq(0, 1), _qq(0, 1, 1)),
                  (_qq(0, 3, 3), _qq(0, 1, 1)),
                  (_qq(0, -1), _qq(0, -1, 1)),
                  (_qq(3//4, 5//4), _qq(3, 5, 4)),
                  (_qq(1, sqrt2), _qq(1, sqrt2, 1)),
                  (_qq(imaginary_unit, 0), _qq(imaginary_unit, 0, 1))]
        for (input, expected) in inputs
            @testset "coordinates $input" begin
                P = Cconic(input)
                _check_point(api, P, expected; curve=Cconic, singular=false, infinite=false)
                @test P.place === nothing
                @test P.ev === nothing
                @test api.plane_equation(P) == conic
                _check_cache_and_chart(api, P)
            end
        end
    end

    @testset "Smooth points at infinity in both charts" begin
        Ccusp = api.punctured_marked_curve(Y^2 - X^3)
        cases = [(Cconic, _qq(1, 1, 0)),
                 (Cconic, _qq(3, -3, 0)),
                 (Ccusp, _qq(0, 1, 0))]
        for (C, input) in cases
            @testset "coordinates $input on $(api.plane_equation(C))" begin
                P = C(input)
                _check_point(api, P, input; curve=C, singular=false, infinite=true)
                @test P.place === nothing
                @test P.ev === nothing
                _check_cache_and_chart(api, P)
            end
        end
    end

    @testset "Mixed infinity: chart functions have poles elsewhere" begin
        eq = (Y-X^2)*(Y-X)+1
        C = api.punctured_marked_curve(eq)
        for high_branch in (false, true)
            @testset "high growth = $high_branch" begin
                input = high_branch ? _qq(0, 1, 0) : _qq(1, 1, 0)
                P = C(input)
                _check_point(api, P, input; curve=C, singular=false, infinite=true)
                ev = _check_cache_and_chart(api, P)
                F = function_field(P)
                x, y = F(gen(base_ring(F))), gen(F)
                if high_branch
                    @test ev(y/x^2) == 1
                    @test ev(x^2*(y-x^2)) == -1
                    @test_throws _POLE_ERROR ev(y/x)
                else
                    @test ev(y/x) == 1
                    @test ev(y/x^2) == 0
                    @test ev(x^2*(y-x)) == 1
                end
            end
        end
    end

    @testset "Singular finite node: both selected branches" begin
        eq = Y^2 - X^2*(X+1)
        C = api.punctured_marked_curve(eq)
        F = function_field(C)
        x, y = F(gen(base_ring(F))), gen(F)
        residues = QQBarFieldElem[]
        places = Hecke.GenOrdIdl[]
        for i in 1:2
            @testset "branch index $i" begin
                P = C(_qq(0, 0); index=i)
                _check_point(api, P, _qq(0, 0, 1); curve=C, singular=true, infinite=false)
                @test P.place !== nothing
                @test P.ev === nothing
                ev = _check_cache_and_chart(api, P)
                push!(places, api.place(P))
                candidates = _finite_fibre(F, 0)
                @test length(candidates) == 2
                @test any(q -> q == api.place(P), candidates)
                c = ev(y/x)
                push!(residues, c)
                @test c^2 == 1
                @test ev((y-c*x)/x^2) == c/2
                @test_throws _POLE_ERROR ev((y+c*x)/x^2)
                Q = C(api.place(P))
                _check_point(api, Q, coordinates(P); curve=C, singular=true, infinite=false)
                @test api.place(Q) === api.place(P)
                @test api.evaluate(Q)(y/x) == c
            end
        end
        @test places[1] != places[2]
        @test Set(residues) == Set(_qq(-1, 1))
        @test_throws _POLE_ERROR C(_qq(0, 0))
        @test_throws BoundsError C(_qq(0, 0); index=0)
        @test_throws BoundsError C(_qq(0, 0); index=3)
    end

    @testset "Singular infinity: two branches with identical plane coordinates" begin
        eq = Y^2 - X^4 - 1
        C = api.punctured_marked_curve(eq)
        F = function_field(C)
        x, y = F(gen(base_ring(F))), gen(F)
        residues = QQBarFieldElem[]
        places = Hecke.GenOrdIdl[]
        for i in 1:2
            @testset "branch index $i" begin
                P = C(_qq(0, 3, 0); index=i)
                _check_point(api, P, _qq(0, 1, 0); curve=C, singular=true, infinite=true)
                @test P.place !== nothing
                ev = _check_cache_and_chart(api, P)
                push!(places, api.place(P))
                candidates = _infinite_places(F)
                @test length(candidates) == 2
                @test any(q -> q == api.place(P), candidates)
                c = ev(y/x^2)
                push!(residues, c)
                @test c^2 == 1
                @test ev(x^2*(y-c*x^2)) == c/2
                @test_throws _POLE_ERROR ev(x^2*(y+c*x^2))
                Q = C(api.place(P))
                _check_point(api, Q, coordinates(P); curve=C, singular=true, infinite=true)
                @test api.place(Q) === api.place(P)
                @test api.evaluate(Q)(y/x^2) == c
            end
        end
        @test places[1] != places[2]
        @test Set(residues) == Set(_qq(-1, 1))
        @test_throws _POLE_ERROR C(_qq(0, 1, 0))
        @test_throws BoundsError C(_qq(0, 1, 0); index=0)
        @test_throws BoundsError C(_qq(0, 1, 0); index=3)
    end

    @testset "Cusps: one branch despite multiplicity" begin
        @testset "Finite cusp" begin
            eq = Y^2 - X^3
            C = api.punctured_marked_curve(eq)
            P = C(_qq(0, 0); index=1)
            _check_point(api, P, _qq(0, 0, 1); curve=C, singular=true, infinite=false)
            ev = _check_cache_and_chart(api, P)
            F = function_field(P)
            x, y = F(gen(base_ring(F))), gen(F)
            @test ev(y/x) == 0
            @test_throws BoundsError C(_qq(0, 0); index=2)
        end
        @testset "Infinite cusp" begin
            eq = Y^2 - X^5
            C = api.punctured_marked_curve(eq)
            P = C(_qq(0, 1, 0); index=1)
            _check_point(api, P, _qq(0, 1, 0); curve=C, singular=true, infinite=true)
            _check_cache_and_chart(api, P)
            @test_throws BoundsError C(_qq(0, 1, 0); index=2)
        end
    end

    @testset "Invalid coordinate inputs" begin
        @test_throws ArgumentError Cconic(_qq(0, 0, 0))
        @test_throws ArgumentError Cconic(_qq(0, 0))
        @test_throws ArgumentError Cconic(_qq(1, 0, 0))
        @test_throws AssertionError Cconic(_qq(1))
        @test_throws AssertionError Cconic(_qq(1, 2, 3, 4))
    end
end

function _test_places(api; zero_y_regression)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)

    @testset "Finite places reuse the supplied field and prime" begin
        F, x, y = _field(Y^2 - X^2 - 1)
        C = api.punctured_marked_curve(F)
        for (a, b) in ((0, 1), (0, -1), (3//4, 5//4))
            @testset "finite point ($a, $b)" begin
                p = _finite_prime(F, a, b)
                P = C(p)
                @test function_field(P) === F
                @test P.place === p
                @test P.ev !== nothing
                _check_point(api, P, _qq(a, b, 1); curve=C, singular=false, infinite=false)
                _check_cache_and_chart(api, P)
            end
        end
    end

    @testset "Finite branches above singular points" begin
        for (eq, expected_count) in ((Y^2-X^2*(X+1), 2), (Y^2-X^3, 1))
            @testset "$eq" begin
                F, x, y = _field(eq)
                C = api.punctured_marked_curve(F)
                ps = _finite_fibre(F, 0)
                @test length(ps) == expected_count
                residues = QQBarFieldElem[]
                for p in ps
                    P = C(p)
                    @test function_field(P) === F
                    @test api.place(P) === p
                    _check_point(api, P, _qq(0, 0, 1); curve=C, singular=true, infinite=false)
                    ev = _check_cache_and_chart(api, P)
                    push!(residues, ev(y/x))
                end
                @test Set(residues) == (expected_count == 2 ? Set(_qq(-1, 1)) : Set(_qq(0)))
            end
        end
    end

    @testset "Infinite places: equal and unequal pole orders" begin
        cases = [(Y^2-X^2-1, [_qq(1, -1, 0), _qq(1, 1, 0)], false),
                 (Y^2-X^3, [_qq(0, 1, 0)], false),
                 (Y^2-X^4-1, [_qq(0, 1, 0), _qq(0, 1, 0)], true),
                 (Y^2-X^5, [_qq(0, 1, 0)], true),
                 (Y^2-X, [_qq(1, 0, 0)], false),
                 (Y^2-2X^2-1, [_qq(1, -sqrt(QQBar(2)), 0), _qq(1, sqrt(QQBar(2)), 0)], false),
                 ((Y-X^2)*(Y-X)+1, [_qq(1, 1, 0), _qq(0, 1, 0)], false)]
        for (eq, expected, singular) in cases
            @testset "$eq" begin
                F, x, y = _field(eq)
                C = api.punctured_marked_curve(F)
                ps = _infinite_places(F)
                @test length(ps) == length(expected)
                images = Tuple{QQBarFieldElem, QQBarFieldElem, QQBarFieldElem}[]
                for p in ps
                    P = C(p)
                    @test function_field(P) === F
                    @test P.place === p
                    @test P.ev !== nothing
                    @test any(target -> _same_projective(coordinates(P), target), expected)
                    _check_point(api, P, coordinates(P); curve=C, singular=singular, infinite=true)
                    push!(images, coordinates(P))
                    _check_cache_and_chart(api, P)
                end
                # Compare multisets projectively, preserving repeated images.
                remaining = copy(images)
                for target in expected
                    j = findfirst(c -> _same_projective(c, target), remaining)
                    @test j !== nothing
                    j === nothing || deleteat!(remaining, j)
                end
                @test isempty(remaining)
            end
        end
    end

    @testset "Place-constructor input validation" begin
        eq = Y^2-X^2-1
        F, x, y = _field(eq)
        G, _, _ = _field(eq)
        @test F !== G
        C = api.punctured_marked_curve(F)
        D = api.punctured_marked_curve(G)
        p = _finite_prime(F, 0, 1)
        @test_throws AssertionError D(p)
        @test_throws AssertionError C(p^2)
    end

    @testset "Identically zero y coordinate at infinity" begin
        if zero_y_regression
            F, x, y = _field(Y)
            C = api.punctured_marked_curve(F)
            @test iszero(y)
            p = only(_infinite_places(F))
            P = C(p)
            _check_point(api, P, _qq(1, 0, 0); curve=C, singular=false, infinite=true)
            _check_cache_and_chart(api, P)
        else
            # Opt in after adding an explicit y == 0 branch to the constructor.
            @test_skip zero_y_regression
        end
    end
end

function _test_parents(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    eq = Y^2 - X^2 - 1

    @testset "A shared parent owns the field and plane equation" begin
        C = api.punctured_marked_curve(eq)
        @test C isa api.PuncturedMarkedCurve
        @test api.plane_equation(C) == eq
        @test function_field(C) === C.function_field
        @test api.plane_equation(C) === C.plane_equation

        F = function_field(C)
        x, y = F(gen(base_ring(F))), gen(F)
        @test defining_constant_field(F) === QQBar
        @test iszero(eq(x, y))

        P = C(_qq(0, 1))
        Q = C(_qq(0, -1))
        Pscaled = C(_qq(0, 3, 3))
        for (point, expected) in ((P, _qq(0, 1, 1)),
                                  (Q, _qq(0, -1, 1)),
                                  (Pscaled, _qq(0, 1, 1)))
            _check_point(api, point, expected;
                         curve=C, singular=false, infinite=false)
            @test point.place === nothing
            @test point.ev === nothing
        end
        @test parent(P) === parent(Q) === parent(Pscaled)
        @test function_field(P) === function_field(Q) === F
        @test api.plane_equation(P) === api.plane_equation(Q) === api.plane_equation(C)

        evP = _check_cache_and_chart(api, P)
        evQ = _check_cache_and_chart(api, Q)
        @test domain(evP) === domain(evQ) === F
        @test evP(y) == 1
        @test evQ(y) == -1
        @test api.place(Pscaled) == api.place(P)
        @test api.place(P) != api.place(Q)
    end

    @testset "Parent construction preserves an existing field" begin
        F, x, y = _field(eq)
        C = api.punctured_marked_curve(F)
        D = api.punctured_marked_curve(F)
        @test C isa api.PuncturedMarkedCurve
        @test D isa api.PuncturedMarkedCurve
        @test function_field(C) === F
        @test function_field(D) === F
        @test api.plane_equation(C)(X, Y) == eq
        @test iszero(api.plane_equation(C)(x, y))

        # A supplied prime belongs to F, and can be used with either parent.
        # This does not require a global cache of parent objects.
        p = _finite_prime(F, 0, 1)
        P, Q = C(p), D(p)
        @test parent(P) === C
        @test parent(Q) === D
        @test api.place(P) === p
        @test api.place(Q) === p
        @test function_field(P) === function_field(Q) === F
        @test _same_projective(coordinates(P), coordinates(Q))

        G, _, _ = _field(eq)
        @test G !== F
        other = api.punctured_marked_curve(G)
        @test_throws AssertionError other(p)
    end

    @testset "Coordinate to place to point roundtrips" begin
        C = api.punctured_marked_curve(eq)
        for input in (_qq(0, 1), _qq(3, -3, 0))
            P = C(input)
            p = api.place(P)
            Q = C(p)
            @test parent(Q) === parent(P) === C
            @test api.place(Q) === p
            @test _same_projective(coordinates(Q), coordinates(P))
            @test api.is_singular(Q) === api.is_singular(P)
            @test api.is_infinite(Q) === api.is_infinite(P)
            _check_cache_and_chart(api, Q)
        end

        # The projective point alone does not identify the branch at a node.
        Cnode = api.punctured_marked_curve(Y^2 - X^2*(X+1))
        F = function_field(Cnode)
        x, y = F(gen(base_ring(F))), gen(F)
        residues = QQBarFieldElem[]
        for i in 1:2
            P = Cnode(_qq(0, 0); index=i)
            Q = Cnode(api.place(P))
            @test parent(Q) === parent(P) === Cnode
            @test api.place(Q) === api.place(P)
            @test _same_projective(coordinates(Q), coordinates(P))
            @test api.is_singular(Q)
            c = api.evaluate(P)(y/x)
            @test api.evaluate(Q)(y/x) == c
            push!(residues, c)
        end
        @test Set(residues) == Set(_qq(-1, 1))
    end

    @testset "Rejected parent inputs" begin
        for bad in (zero(parent(eq)), X*Y - 1, 2Y^2 - X, X*Y^2 + Y + 1)
            @test_throws ArgumentError api.punctured_marked_curve(bad)
        end
        _, (U, V, W) = polynomial_ring(QQBar, [:gp_U, :gp_V, :gp_W]; cached=false)
        @test_throws AssertionError api.punctured_marked_curve(V^2-U-W)
        _, (Uq, Vq) = polynomial_ring(QQ, [:gp_Uq, :gp_Vq]; cached=false)
        @test_throws AssertionError api.punctured_marked_curve(Vq^2-Uq)

        # Monic over QQBar(x) alone does not satisfy the plane-model restriction.
        H, _, _ = _field(X*Y - 1)
        @test_throws ArgumentError api.punctured_marked_curve(H)
    end
end

function _test_equality(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_eq_X, :gp_eq_Y]; cached=false)

    @testset "Smooth affine equality and cache state" begin
        C = api.punctured_marked_curve(Y^2 - X^2 - 1)
        P = C(_qq(0, 1))
        Q = C(_qq(0, 3, 3))
        R = C(_qq(0, -1))

        @test P.place === nothing
        @test P.ev === nothing
        @test Q.place === nothing
        @test Q.ev === nothing
        @test P == P
        @test P == Q
        @test Q == P
        @test !(P == R)
        @test !(R == P)

        # Equality must be unchanged when only one point has a cached place.
        api.place(P)
        @test P == Q
        @test Q == P

        # A place-constructed point has its evaluator populated immediately.
        from_place = C(api.place(P))
        @test from_place.ev !== nothing
        @test P == from_place
        @test Q == from_place
        @test from_place == Q

        _check_cache_and_chart(api, P)
        @test P == Q
        @test Q == P
        _check_cache_and_chart(api, Q)
        @test P == Q
        @test P == from_place
        @test !(P == R)
    end

    @testset "Parent identity is required, even for a shared function field" begin
        F, _, _ = _field(Y^2 - X^2 - 1)
        C = api.punctured_marked_curve(F)
        D = api.punctured_marked_curve(F)
        @test C !== D
        @test function_field(C) === function_field(D)
        P, Q = C(_qq(0, 1)), D(_qq(0, 1))
        @test !(P == Q)
        @test !(Q == P)

        p = api.place(P)
        P_cached, Q_cached = C(p), D(p)
        @test api.place(P_cached) === api.place(Q_cached)
        @test !(P_cached == Q_cached)
        @test !(Q_cached == P_cached)
    end

    @testset "Smooth infinity points and projective rescaling" begin
        C = api.punctured_marked_curve(Y^2 - X^2 - 1)
        P = C(_qq(1, 1, 0))
        Q = C(_qq(-3, -3, 0))
        R = C(_qq(1, -1, 0))
        @test P == P
        @test P == Q
        @test Q == P
        @test !(P == R)
        @test !(R == P)
        from_place = C(api.place(P))
        @test P == from_place
        @test Q == from_place
        @test from_place == Q
        _check_cache_and_chart(api, Q)
        @test P == Q
        @test !(Q == R)
    end

    @testset "Affine and infinite points with the same X:Y ratio differ" begin
        C = api.punctured_marked_curve(Y - X)
        P = C(_qq(1, 1, 1))
        Q = C(_qq(1, 1, 0))
        @test !api.is_singular(P)
        @test !api.is_singular(Q)
        @test !(P == Q)
        @test !(Q == P)
        @test P == C(_qq(2, 2, 2))
        @test Q == C(_qq(2, 2, 0))
    end

    @testset "Distinct smooth points in different infinity charts" begin
        C = api.punctured_marked_curve(Y^2 + X^2*Y + X)
        P = C(_qq(1, 0, 0))
        Q = C(_qq(0, 1, 0))
        @test !api.is_singular(P)
        @test !api.is_singular(Q)
        @test !(P == Q)
        @test !(Q == P)
        @test P == C(_qq(-2, 0, 0))
        @test Q == C(_qq(0, 7, 0))
    end

    @testset "Singular branches are distinguished by their places" begin
        fixtures = (
            (Y^2 - X^2*(X + 1), _qq(0, 0, 1), false),
            (Y^2 - X^4 - 1, _qq(0, 1, 0), true),
        )
        for (eq, coords, infinite) in fixtures
            @testset "$eq" begin
                C = api.punctured_marked_curve(eq)
                branches = [C(coords; index=i) for i in 1:2]
                scaled = [C(QQBar(3) .* coords; index=i) for i in 1:2]
                @test _same_projective(coordinates(branches[1]), coordinates(branches[2]))
                @test api.place(branches[1]) != api.place(branches[2])
                @test !(branches[1] == branches[2])
                @test !(branches[2] == branches[1])

                for P in branches
                    _check_point(api, P, coords; curve=C, singular=true, infinite=infinite)
                    @test P == P
                    from_place = C(api.place(P))
                    @test P == from_place
                    @test from_place == P

                    # Match actual places; do not assume factorization order.
                    same_branch = only(Q for Q in scaled if api.place(Q) == api.place(P))
                    other_branch = only(Q for Q in scaled if api.place(Q) != api.place(P))
                    @test P == same_branch
                    @test same_branch == P
                    @test !(P == other_branch)
                    @test !(other_branch == P)

                    _check_cache_and_chart(api, P)
                    @test P == from_place
                    @test P == same_branch
                    @test !(P == other_branch)
                end
            end
        end
    end

    @testset "Smooth and singular plane points are unequal" begin
        C = api.punctured_marked_curve(Y^2 - X^2*(X + 1))
        P = C(_qq(0, 0, 1); index=1)
        Q = C(_qq(-1, 0, 1))
        @test api.is_singular(P)
        @test !api.is_singular(Q)
        @test !(P == Q)
        @test !(Q == P)
    end
    return nothing
end

function _check_branch_collection(api, branches, C, coords, expected_count,
                                  residue_function, expected_residues;
                                  singular, infinite)
    @test branches isa AbstractVector
    @test length(branches) == expected_count
    F = function_field(C)
    x, y = F(gen(base_ring(F))), gen(F)
    residues = QQBarFieldElem[]
    branch_places = Hecke.GenOrdIdl[]
    for B in branches
        _check_point(api, B, coords; curve=C, singular=singular, infinite=infinite)
        p = api.place(B)
        @test is_prime(p)
        @test Hecke.field(order(p)) === F
        push!(branch_places, p)
        push!(residues, api.evaluate(B)(residue_function(x, y)))
    end
    @test Set(residues) == Set(expected_residues)
    @test all(branch_places[i] != branch_places[j]
              for i in eachindex(branch_places) for j in i+1:length(branch_places))

    # Every returned branch must itself support the same enumeration. In
    # particular, this must work when branches were reconstructed from places.
    for (i, B) in enumerate(branches)
        @testset "Enumerating returned branch $i" begin
            selected_place, selected_ev = B.place, B.ev
            again = api.places_above(B)
            @test B.place === selected_place
            @test B.ev === selected_ev
            @test length(again) == expected_count
            @test all(parent(Q) === C for Q in again)
            @test all(_same_projective(coordinates(Q), coords) for Q in again)
            again_places = [api.place(Q) for Q in again]
            @test all(count(q -> q == p, again_places) == 1 for p in branch_places)
        end
    end
    return nothing
end

function _test_branches(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    fixtures = (
        ("Smooth affine point", Y^2-X^2-1, _qq(0, 1, 1),
         false, false, 1, (x, y) -> y, _qq(1)),
        ("Smooth point at infinity", Y^2-X^2-1, _qq(1, 1, 0),
         false, true, 1, (x, y) -> y/x, _qq(1)),
        ("Finite node", Y^2-X^2*(X+1), _qq(0, 0, 1),
         true, false, 2, (x, y) -> y/x, _qq(-1, 1)),
        ("Finite cusp", Y^2-X^3, _qq(0, 0, 1),
         true, false, 1, (x, y) -> y/x, _qq(0)),
        ("Two branches at infinity", Y^2-X^4-1, _qq(0, 1, 0),
         true, true, 2, (x, y) -> y/x^2, _qq(-1, 1)),
        ("One singular branch at infinity", Y^2-X^5, _qq(0, 1, 0),
         true, true, 1, (x, y) -> x^2/y, _qq(0)),
    )
    for (label, eq, coords, singular, infinite, count_branches, f, values) in fixtures
        @testset "$label" begin
            C = api.punctured_marked_curve(eq)
            # A selected branch is only needed for the point-taking overload;
            # places_above(C, coords) must not require an index from its caller.
            P = singular ? C(copy(coords); index=1) : C(copy(coords))

            @testset "From a coordinate-constructed point" begin
                selected_place, selected_ev = P.place, P.ev
                branches = api.places_above(P)
                @test P.place === selected_place
                @test P.ev === selected_ev
                _check_branch_collection(api, branches, C, coords, count_branches,
                    f, values; singular=singular, infinite=infinite)
            end

            @testset "Directly from plane coordinates" begin
                branches = api.places_above(C, copy(coords))
                _check_branch_collection(api, branches, C, coords, count_branches,
                    f, values; singular=singular, infinite=infinite)
            end

            @testset "From a place-constructed point" begin
                Q = C(api.place(P))
                selected_place, selected_ev = Q.place, Q.ev
                branches = api.places_above(Q)
                @test Q.place === selected_place
                @test Q.ev === selected_ev
                _check_branch_collection(api, branches, C, coords, count_branches,
                    f, values; singular=singular, infinite=infinite)
            end
        end
    end
end

function _test_divisors(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)

    @testset "Degree-one divisors and lazy evaluation" begin
        fixtures = (
            ("Smooth finite", Y^2-X^2-1, _qq(0, 1, 1), false),
            ("Smooth infinite", Y^2-X^2-1, _qq(1, 1, 0), false),
            ("Singular finite", Y^2-X^2*(X+1), _qq(0, 0, 1), true),
            ("Singular infinite", Y^2-X^4-1, _qq(0, 1, 0), true),
        )
        for (label, eq, coords, singular) in fixtures
            @testset "$label" begin
                C = api.punctured_marked_curve(eq)
                P = singular ? C(copy(coords); index=1) : C(copy(coords))
                @test P.ev === nothing
                D = Hecke.divisor(P)
                p = api.place(P)
                @test D isa Hecke.Divisor
                @test function_field(D) === function_field(C)
                @test D == Hecke.divisor(p)
                @test degree(D) == 1
                @test Hecke.valuation(D, p) == 1
                @test P.ev === nothing
                @test Hecke.divisor(P) == D
                @test P.place === p

                # A point built from the same place has an evaluator already;
                # divisor conversion must preserve that cached map as well.
                Q = C(p)
                ev = Q.ev
                @test !isnothing(ev)
                @test Hecke.divisor(Q) == D
                @test Q.ev === ev
                @test Q.place === p
            end
        end
    end

    @testset "Different branches give different divisors" begin
        C = api.punctured_marked_curve(Y^2-X^2*(X+1))
        P = C(_qq(0, 0, 1); index=1)
        Q = C(_qq(0, 0, 1); index=2)
        @test _same_projective(coordinates(P), coordinates(Q))
        p, q = api.place(P), api.place(Q)
        @test p != q
        D, E = Hecke.divisor(P), Hecke.divisor(Q)
        # These are actual divisors, not divisor classes: the difference may
        # be principal, but it is not the zero divisor.
        @test D != E
        @test degree(D-E) == 0
        @test D-E != trivial_divisor(function_field(C))
        @test Hecke.valuation(D, q) == 0
        @test Hecke.valuation(E, p) == 0
        @test Hecke.valuation(D-E, p) == 1
        @test Hecke.valuation(D-E, q) == -1
        @test P.ev === nothing
        @test Q.ev === nothing
    end
end

function _test_convenience(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    C = api.punctured_marked_curve(Y^2-X^2-1)

    @testset "Exact scalar and vector coordinate coercions" begin
        cases = [
            ("integer vector", () -> C([0, 1]), _qq(0, 1, 1)),
            ("integer arguments", () -> C(0, 1), _qq(0, 1, 1)),
            ("three integer arguments", () -> C(0, 3, 3), _qq(0, 1, 1)),
            ("rational vector", () -> C([3//4, 5//4]), _qq(3, 5, 4)),
            ("rational arguments", () -> C(3//4, 5//4), _qq(3, 5, 4)),
            ("big integers", () -> C(BigInt(0), BigInt(-1)), _qq(0, -1, 1)),
            ("heterogeneous vector", () -> C(Any[0, QQBar(1)]), _qq(0, 1, 1)),
            ("vector view", () -> C(view([0, 3, 3, 99], 1:3)), _qq(0, 1, 1)),
            ("algebraic arguments", () -> C(QQBar(1), sqrt(QQBar(2))),
             _qq(1, sqrt(QQBar(2)), 1)),
            ("infinity arguments", () -> C(3, -3, 0), _qq(1, -1, 0)),
        ]
        for (label, construct, expected) in cases
            @testset "$label" begin
                P = construct()
                _check_point(api, P, expected; curve=C, singular=false,
                             infinite=iszero(expected[3]))
                @test P.place === nothing
                @test P.ev === nothing
                @test P.associated_places === nothing
                _check_cache_and_chart(api, P)
            end
        end
    end

    @testset "Convenience constructors preserve branch selection" begin
        Cnode = api.punctured_marked_curve(Y^2-X^2*(X+1))
        F = function_field(Cnode)
        x, y = F(gen(base_ring(F))), gen(F)
        variants = [
            ("integer vector", i -> Cnode([0, 0]; index=i)),
            ("vector view", i -> Cnode(view([0, 0, 1], 1:2); index=i)),
            ("two arguments", i -> Cnode(0, 0; index=i)),
            ("three arguments", i -> Cnode(0, 0, 3; index=i)),
            ("algebraic arguments", i -> Cnode(QQBar(0), QQBar(0); index=i)),
        ]
        for (label, construct) in variants
            @testset "$label" begin
                residues = QQBarFieldElem[]
                for i in 1:2
                    P = construct(i)
                    _check_point(api, P, _qq(0, 0, 1);
                                 curve=Cnode, singular=true, infinite=false)
                    @test api.place(P) == api.place(Cnode(_qq(0, 0); index=i))
                    push!(residues, api.evaluate(P)(y/x))
                end
                @test Set(residues) == Set(_qq(-1, 1))
                @test_throws BoundsError construct(3)
            end
        end
    end

    @testset "Coercion preserves input validation" begin
        @test_throws ArgumentError C(0, 0, 0)
        @test_throws ArgumentError C([0, 0])
        @test_throws AssertionError C(1)
        @test_throws AssertionError C(1, 2, 3, 4)
        @test_throws AssertionError C(Int[])
    end
end

function _test_display(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    C = api.punctured_marked_curve(Y^2-X^2-1)

    # Capture the provided stream and stdout separately. This catches a stray
    # println without its io argument, without prescribing polynomial formatting.
    function render(obj)
        output = IOBuffer()
        escaped = mktemp() do _, capture
            redirect_stdout(capture) do
                show(output, obj)
            end
            flush(capture)
            seekstart(capture)
            read(capture, String)
        end
        @test isempty(escaped)
        text = String(take!(output))
        @test !isempty(strip(text))
        return text
    end

    @testset "Parent display uses the provided stream" begin
        F = function_field(C)
        eq = api.plane_equation(C)
        render(C)
        @test function_field(C) === F
        @test api.plane_equation(C) === eq
    end

    @testset "Smooth point display leaves both caches lazy" begin
        for input in (_qq(0, 1), _qq(1, 1, 0))
            P = C(input)
            @test P.place === nothing
            @test P.ev === nothing
            associated_before = P.associated_places
            coords_before = coordinates(P)
            text = render(P)
            @test P.place === nothing
            @test P.ev === nothing
            @test P.associated_places === associated_before
            @test coordinates(P) == coords_before
            @test parent(P) === C
        end
    end

    @testset "Singular point display preserves the selected place" begin
        Cnode = api.punctured_marked_curve(Y^2-X^2*(X+1))
        P = Cnode(_qq(0, 0); index=1)
        p = P.place
        associated_before = P.associated_places
        @test p !== nothing
        @test P.ev === nothing
        text = render(P)
        @test P.place === p
        @test P.ev === nothing
        @test parent(P) === Cnode
        @test P.associated_places === associated_before
    end
end

# Optional contract tests. The supplied source comments out irreducibility
# validation, so these are deliberately not part of the default test groups.
# Enable them after restoring absolute-irreducibility validation in construction.
function _test_irreducibility(api)
    _, (X, Y) = polynomial_ring(QQBar, [:gp_X, :gp_Y]; cached=false)
    validation_error = Union{ArgumentError, AssertionError}

    @testset "Reducible equations are rejected before creating a field" begin
        for eq in ((Y-X)*(Y+X), Y^2-2X^2, Y^2)
            @testset "$eq" begin
                @test_throws validation_error api.plane_equation_to_function_field(eq)
                @test_throws validation_error api.punctured_marked_curve(eq)
            end
        end
    end

    @testset "Absolutely irreducible equations remain accepted" begin
        for eq in (Y, Y^2-X, Y^2-X^2-1)
            C = api.punctured_marked_curve(eq)
            F = function_field(C)
            x, y = F(gen(base_ring(F))), gen(F)
            @test iszero(eq(x, y))
            @test api.plane_equation(C) == eq
        end
    end
end

"""
    runtests(api::Module=Main; groups=(:helpers, :parents, :evaluation,
                                     :coordinates, :places, :convenience,
                                     :equality, :branches, :divisors, :display),
             zero_y_regression=false)

Run against PuncturedMarkedCurve / GeometricPoint definitions already loaded
in `api`. All expected coordinate and residue values are exact. Points made
through the same parent must share its field and plane equation. Tests do not
assume a particular factorization order or projective normalization.
Display checks test IO routing and cache preservation without fixing wording.
New functionality is tested against its intended contract: convenience
constructors forward branch-selection keywords, equality distinguishes
normalization branches, and places_above enumerates all branches regardless of
how its input point was created. These tests deliberately expose source bugs.

Set `zero_y_regression=true` after fixing the zero-numerator valuation loop;
the pasted version can loop forever on that input. Source syntax errors must
be fixed before including the implementation. Failures are not suppressed.
The optional `:irreducibility` group checks rejection of reducible equations;
it is excluded by default because that validation is commented out in the paste.
"""
function runtests(api::Module=Main; groups=_GROUPS, zero_y_regression=false)
    all(g -> g in _AVAILABLE_GROUPS, groups) ||
        throw(ArgumentError("Unknown test group; choose from $(_AVAILABLE_GROUPS)"))

    @testset "PuncturedMarkedCurve and GeometricPoint" begin
        if :helpers in groups
            @testset "Helpers" begin
                _test_helpers(api)
            end
        end
        if :parents in groups
            @testset "Shared curve parents" begin
